await page.goto('https://httpbin.org/forms/post');
await page.getByLabel('Customer name').fill('Alex');
await page.getByRole('button', {name: 'Submit order'}).click();
await page.evaluate(() => ({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: document.body.innerText, values: [document.body.innerText.match(/customer name:\s*([^\n]+)/i)?.[1]], answer: document.body.innerText.match(/customer name:\s*([^\n]+)/i)?.[1] || ''}));

await page.goto('https://httpbin.org/forms/post');
await page.getByLabel('Customer name').fill('Alex');
await page.getByRole('button', {name: 'Submit order'}).click();
await page.evaluate(() => { const text = document.body.innerText; const value = JSON.parse(text).form.custname; return cu.claim({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: '"custname": "' + value + '"', values: [value], answer: value}); });

await page.goto('https://the-internet.herokuapp.com/login');
const creds = await page.evaluate(() => document.body.innerText.match(/Username\s*:?\s*([^\n]+)[\s\S]*?Password\s*:?\s*([^\n]+)/i)?.slice(1));
if (creds) {
  await cu.fill('Username', creds[0].trim());
  await cu.fill('Password', creds[1].trim());
  await cu.click('Login');
}
await page.evaluate(() => { const text = document.body.innerText; const match = text.match(/(?:You logged into a secure area!|Your username is invalid!|Your password is invalid!|You logged out of the secure area!)/); const answer = match?.[0] || ''; return cu.claim({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: answer, values: [], answer}); });

await page.goto('https://the-internet.herokuapp.com/login');
const creds = await page.evaluate(() => { const t = document.body.innerText; const u = t.match(/Username\s*:?\s*([^\n]+)/i)?.[1]; const p = t.match(/Password\s*:?\s*([^\n]+)/i)?.[1]; return [u?.trim(), p?.trim()]; });
if (creds[0] && creds[1]) { await cu.fill('Username', creds[0]); await cu.fill('Password', creds[1]); await cu.click('Login'); }
await page.evaluate(() => { const text = document.body.innerText; const m = text.match(/(?:You logged into a secure area!|Your username is invalid!|Your password is invalid!|You logged out of the secure area!)/); const answer = m?.[0] || ''; return cu.claim({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: answer, values: [], answer}); });

await page.goto('https://www.w3schools.com/html/html_forms.asp');
await page.getByRole('button', {name: 'Submit'}).click();
await page.evaluate(() => cu.claim({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: document.body.innerText.includes('The form data was sent to the server') ? 'The form data was sent to the server' : document.body.innerText.slice(0, 500), values: [...new URLSearchParams(location.search).entries()], answer: location.href}));

await page.goto('https://www.w3schools.com/html/html_forms.asp');
await page.getByRole('button', {name: 'Submit'}).first().click();
await page.evaluate(() => cu.claim({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: document.body.innerText.includes('HTML Forms') ? 'HTML Forms' : '', values: [...new URLSearchParams(location.search).entries()], answer: location.href}));
